  function show(name,push=false){if(!routes.includes(name))name='overview';document.body.dataset.page=name;document.querySelectorAll('.view').forEach(v=>v.hidden=v.dataset.view!==name);document.querySelectorAll('[data-route]').forEach(a=>{const primary=a.parentElement?.id==='nav-links'&&!a.classList.contains('nav-cta'),active=primary&&a.dataset.route===name;a.classList.toggle('on',active);active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current')});if(push){const route=name==='overview'?'':name==='model'?'audit/':`${name}/`;history.pushState({},'',`${siteBase}${route}`)}document.title=`CAUSALIS — ${titles[name]}`;nav.dataset.menu='closed';nav.dataset.stuck='false';burger?.setAttribute('aria-expanded','false');scrollTo({top:0,behavior:push?'smooth':'auto'});setTimeout(()=>{initDynamic(name);initReveal(name);if(push){const heading=document.querySelector(`[data-view="${name}"] h1`);heading?.setAttribute('tabindex','-1');heading?.focus({preventScroll:true})}},40)}
  document.addEventListener('click',e=>{const a=e.target.closest('[data-route]'),modified=e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey;if(a&&!modified&&a.target!=='_blank'){e.preventDefault();if(document.body.dataset.page===a.dataset.route)scrollTo({top:0,behavior:'smooth'});else show(a.dataset.route,true)}const q=e.target.closest('.faq-item button');if(q){const item=q.parentElement,open=!item.classList.contains('open'),answer=item.querySelector('.faq-answer');item.classList.toggle('open',open);q.setAttribute('aria-expanded',String(open));q.querySelector('span').textContent=open?'−':'+';answer.hidden=!open}if(nav.dataset.menu==='open'&&!e.target.closest('#nav')){nav.dataset.menu='closed';burger?.setAttribute('aria-expanded','false')}});
