  function initReveal(name){const root=document.querySelector(`[data-view="${name}"]`);if(!root)return;const nodes=root.querySelectorAll('.sect h2,.card,.mcard,.framework-grid article,.regime-grid article,.observatory-grid article,.questions-grid li,.instrument,.research-steps article,.case-flow article,.schema-map article,.rationale-list article,.comparison-grid article,.boundary-matrix>div,.notation-list article,.result-legend article');nodes.forEach(n=>n.dataset.reveal='');const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('revealed');io.unobserve(e.target)}}),{threshold:.08,rootMargin:'0px 0px -35px'});nodes.forEach(n=>io.observe(n))}
  const wall = document.querySelector('#wall');if(wall)wall.innerHTML=Array(32).fill('autonomy is a state transition · causality is an intervention · capital remembers · policy becomes exposure · consequence propagates · ∂x/∂a ≠ 0 · ').join(' ');
