    if(typeof value==='number'&&schema.minimum!=null&&value<schema.minimum)issues.push({path,message:`Expected a value greater than or equal to ${schema.minimum}.`});
    if(Array.isArray(value)){if(schema.minItems!=null&&value.length<schema.minItems)issues.push({path,message:`Expected at least ${schema.minItems} item.`});if(schema.items)value.forEach((item,index)=>validateSchema(item,schema.items,`${path}[${index}]`,issues))}
    if(value!==null&&typeof value==='object'&&!Array.isArray(value)){(schema.required||[]).forEach(key=>{if(!Object.prototype.hasOwnProperty.call(value,key))issues.push({path:`${path}.${key}`,message:'Required property is missing.'})});Object.entries(schema.properties||{}).forEach(([key,child])=>{if(Object.prototype.hasOwnProperty.call(value,key))validateSchema(value[key],child,`${path}.${key}`,issues)})}
