  function escapeHtml(value){return String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]))}
  function renderAudit(report){const root=document.querySelector('#audit-results');if(!root)return;const counts=report.results.reduce((a,r)=>(a[r.status]++,a),{pass:0,fail:0,not_provided:0});const schemaDetail=report.schema.valid?'<p>The document satisfies the published structural schema.</p>':`<p>${report.schema.issues.length} schema issue${report.schema.issues.length===1?'':'s'} found.</p><ul>${report.schema.issues.map(issue=>`<li><code>${escapeHtml(issue.path)}</code> ${escapeHtml(issue.message)}</li>`).join('')}</ul>`;root.innerHTML=`<div class="audit-report-head"><span>REPORT GENERATED</span><button id="download-report" type="button">Export JSON</button></div><h3>${escapeHtml(report.agent||'Unnamed mandate')}</h3><p class="audit-time">${escapeHtml(report.generatedAt)} · ${escapeHtml(report.chain||'chain not provided')}</p><div class="audit-schema" data-valid="${report.schema.valid}"><b>${report.schema.valid?'SCHEMA PASS':'SCHEMA ISSUES'}</b><span>${escapeHtml(report.schema.id)}</span>${schemaDetail}</div><div class="audit-summary"><span class="pass"><b>${counts.pass}</b> pass</span><span class="fail"><b>${counts.fail}</b> fail</span><span class="missing"><b>${counts.not_provided}</b> not provided</span></div><div class="audit-rule-results">${report.results.map(r=>`<article data-status="${r.status}"><span>${r.status.replace('_',' ')}</span><code>${r.id}</code><div><b>${r.label}</b><small>${r.path}</small><p>${r.reason}</p></div></article>`).join('')}</div><div class="audit-disclosure"><b>Verification boundary</b><p>${report.verificationBoundary}</p></div>`;root.querySelector('#download-report').onclick=()=>downloadJson(report,`causalis-audit-${new Date().toISOString().slice(0,10)}.json`)}
