  function initAudit(){const input=document.querySelector('#mandate-input'),results=document.querySelector('#audit-results'),run=document.querySelector('#run-audit');if(!input||input.dataset.ready)return;input.dataset.ready='true';run.onclick=async()=>{const original=run.textContent;run.disabled=true;run.textContent='Validating…';try{const data=JSON.parse(input.value);const schema=await getMandateSchema(),issues=validateSchema(data,schema);const report={standard:'CAUSALIS Mandate Audit v0.1',schema:{id:schema.$id||'unknown',valid:issues.length===0,issues},generatedAt:new Date().toISOString(),agent:readPath(data,'agent.name')||null,chain:readPath(data,'agent.chain')||null,results:evaluateMandate(data),verificationBoundary:'This report validates declarations in the supplied mandate only. It does not verify deployed code, program ownership, runtime behavior, financial safety or future outcomes.'};renderAudit(report)}catch(error){showAuditError(results,error instanceof SyntaxError?'INVALID JSON':'AUDIT ERROR',error instanceof SyntaxError?'The mandate could not be parsed.':'The audit could not be completed.',error.message)}finally{run.disabled=false;run.textContent=original}};document.querySelector('#clear-audit').onclick=()=>{input.value='';results.innerHTML='<div class="audit-empty"><span>NO REPORT</span><h3>Waiting for a mandate.</h3><p>Results will cite the schema, a rule ID, status and exact input path.</p></div>';input.focus()};document.querySelector('#load-template').onclick=()=>loadAuditAsset('downloads/causalis-audit/mandate.template.json',input,results);document.querySelector('#load-example').onclick=()=>loadAuditAsset('downloads/causalis-audit/examples/valid.mandate.json',input,results);document.querySelector('#mandate-file').onchange=event=>{const file=event.target.files?.[0];if(!file)return;if(file.size>1024*1024){showAuditError(results,'FILE TOO LARGE','The mandate was not opened.','Choose a JSON file smaller than 1 MB.');event.target.value='';return}const reader=new FileReader();reader.onload=()=>{input.value=String(reader.result||'');input.focus()};reader.onerror=()=>showAuditError(results,'FILE ERROR','The mandate was not opened.',reader.error?.message||'The browser could not read this file.');reader.readAsText(file)}}
  initSkillCommand();show(routeFromPath());tick();
